"INSERT OR IGNORE INTO events (slug, city, title, organization_id, venue_name, venue_address, start_at, end_at, start_utc, end_utc, timezone, format, description_short, description_long, registration_url, cost_type, cost_min, cost_max, cost_notes, cpe_eligible, cpe_hours, cpe_body, cpe_notes, topics, audience_level, status, source, source_url, reviewer_notes, hold, auto_publish_at) VALUES ('secureworld-new-york-city-2026-2026-10-29', 'newyork', 'SecureWorld New York City 2026', (SELECT id FROM organizations WHERE slug='secureworld'), 'New York Marriott Marquis', '1535 Broadway, New York, NY 10036', '2026-10-29T09:00:00', '2026-10-29T17:00:00', '2026-10-29T13:00:00.000Z', '2026-10-29T21:00:00.000Z', 'America/New_York', 'in_person', 'The eighth annual SecureWorld conference in New York for senior security and IT leaders', 'The eighth annual SecureWorld conference in New York for senior security and IT leaders. It has keynotes, panels, workshops and an exhibit hall, with an agenda guided by a CISO advisory council covering risk management, cloud security, compliance and cyber resilience.', 'https://www.secureworld.io/events/new-york-ny-2026', 'unknown', NULL, NULL, 'Paid; price not shown on the pages I could read', 1, 12.0, 'self_reported', '6-12 CPE (per event listing)', '[\"grc\", \"cloud\", \"leadership\", \"social\"]', 'practitioner', 'pending_review', 'research', 'https://www.secureworld.io/events', 'Research 2026-10-22 from https://www.secureworld.io/events. Times are placeholders; the page gives no time. Publishes automatically in 24 hours unless held or rejected. Research note: Date and venue from secureworld.io/events; street address is the Marriott Marquis''s public address, not stated on the page. Description from a conference listing page.', 0, datetime('now','+1 day'));",
